    eta_bar = progress.ProgressBar(maxvalue=output_length) if menu.options.eta else None

    observed_chars = set()
    observed_count = [0]
    char_frequency = {}
    observed_chars_lock = threading.Lock()

    # Renders positions resolved so far, order-independent: "_" not attempted, "?" no delay found.
    def _render_output_so_far():
      furthest = 0
      chars = []
      for pos in range(1, output_length + 1):
        ascii_char = results_by_position.get(pos)
        if ascii_char == UNRESOLVED_POSITION:
          chars.append(settings.UNRESOLVED_CHAR)
          furthest = pos
        elif ascii_char is not None:
          ch = chr(ascii_char)
          chars.append(ch if ch.isprintable() else " ")
          furthest = pos
        else:
          chars.append("_")
      return checks.progress_display_text(chars, furthest, output_length)

    # Rewrite the progress line with the characters resolved so far.
    def _print_progress():
      # Asked for as an estimate rather than as the text: how much is left, and how long it will take.
      if eta_bar is not None:
        eta_bar.progress(sum(1 for _pos in range(1, output_length + 1) if results_by_position.get(_pos) is not None))
        return
      if settings.VERBOSITY_LEVEL == 0:
        progress_msg = base_progress_msg.rstrip(".") + ": " + _render_output_so_far()
        settings.print_data_to_stdout(settings.END_LINE.CR + settings.print_info_msg(progress_msg))

    # Pre-populates results_by_position from an interrupted prior run's partial value.
    def _load_partial_progress():
      if _stored_partial is None:
        return
      body = _stored_partial[len(settings.PARTIAL_VALUE_MARKER):]
      try:
        stored_length, pairs = body.split(":", 1)
        # Against the length as measured rather than as read: a run reading fewer of them is reading
        # the same output, and the positions past this run's limit are not among the ones it reads.
        if int(stored_length) != full_output_length:
          return
        for pair in pairs.split(","):
          if not pair:
            continue
          pos_str, ord_str = pair.split("=")
          if int(pos_str) <= output_length:
