            else:
              hi = mid
          except KeyboardInterrupt:
            if threaded:
              raise
            checks.handle_exploitation_interrupt(filename, url)
        return (lo, True) if lo >= min_ord else (None, True)

      ascii_char, from_full_range = _bisect_chars()

